//! Render/review differential (P06.2): plans built by the real
//! `buildDeployPlan`, expected bytes from the real `render.ts` and
//! `review.ts`. TOML/JSON/preview compare byte-exact; diffs compare
//! (changed, lines); the V8-unstable throws assert outcome-class
//! (TS threw) while native pins the stable message. Previous-plan
//! shape messages ran through the real `loadPreviousPlan` over temp
//! files. Regenerate with `bun /tmp/p062-vectors.ts` plus this emitter.
use can_preparation::input::decode_tree;
use can_preparation::render::{render_plan_json, render_wrangler_toml};
use can_preparation::review::{check_previous_plan, diff_plans, format_preview, PlanDiff};

fn decode(json: &str) -> can_preparation::input::Node {
    decode_tree(json.as_bytes()).unwrap()
}

